#!/usr/bin/env bash
# Regenerate the web API types from the api's OpenAPI spec:
#   web/openapi.json          dumped from app.openapi() inside the api image
#   web/src/lib/api-types.ts  generated by openapi-typescript inside node:24-slim
#
#   scripts/gen-api-types.sh
#
# Needs only Docker. Both steps run in containers, so the output is the same on
# Linux, macOS and Windows (Git Bash): the api image installs the pinned versions
# in api/constraints.txt, and the files are written as UTF-8 with LF line endings.
set -euo pipefail

OPENAPI_TYPESCRIPT=openapi-typescript@7.4.4
NODE_IMAGE=node:24-slim
API_IMAGE=reach-loop-api:gen-types

root="$(cd "$(dirname "$0")/.." && pwd)"
cd "$root"

# Volume mounts need a host path Docker understands, and files written into the
# mount should belong to the user, not root.
user_args=()
case "$(uname -s)" in
  MINGW* | MSYS* | CYGWIN*)
    export MSYS_NO_PATHCONV=1     # stop Git Bash rewriting /web into C:/Program Files/Git/web
    host_web="$(cd web && pwd -W)" # C:/Users/... instead of /c/Users/...
    ;;
  *)
    host_web="$root/web"
    user_args=(--user "$(id -u):$(id -g)")
    ;;
esac

echo "==> Building $API_IMAGE (pinned versions from api/constraints.txt)"
docker build --quiet --platform linux/amd64 -f api/Dockerfile -t "$API_IMAGE" . >/dev/null

echo "==> Dumping the OpenAPI spec to web/openapi.json"
docker run --rm --platform linux/amd64 "${user_args[@]}" -v "$host_web:/web" "$API_IMAGE" python -c '
import json
from app.main import app
with open("/web/openapi.json", "w", encoding="utf-8", newline="\n") as f:
    json.dump(app.openapi(), f, indent=2, ensure_ascii=False)
    f.write("\n")
'

echo "==> Generating web/src/lib/api-types.ts with $OPENAPI_TYPESCRIPT"
docker run --rm "${user_args[@]}" -e HOME=/tmp -e npm_config_update_notifier=false \
  -v "$host_web:/web" -w /web "$NODE_IMAGE" \
  npx --yes "$OPENAPI_TYPESCRIPT" openapi.json -o src/lib/api-types.ts

echo "==> Done. Commit web/openapi.json and web/src/lib/api-types.ts together with the model change."
git --no-pager diff --stat -- web/openapi.json web/src/lib/api-types.ts
